using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;
using Azure;

namespace Azure.ResourceManager
{
    internal static class ResponseErrorConverter
    {
        private static JsonSerializerOptions s_options;

        internal static JsonSerializerOptions Options
        {
            get
            {
                if (s_options == null)
                {
                    var options = new JsonSerializerOptions();
                    options.TypeInfoResolverChain.Add(ResponseErrorContext.Default);
                    s_options = options;
                }
                return s_options;
            }
        }

        internal static void Serialize(Utf8JsonWriter writer, ResponseError error)
        {
            JsonSerializer.Serialize(writer, error, Options.GetTypeInfo(typeof(ResponseError)));
        }

        internal static ResponseError Deserialize(string json)
        {
            return (ResponseError)JsonSerializer.Deserialize(json, Options.GetTypeInfo(typeof(ResponseError)));
        }
    }

    [JsonSourceGenerationOptions]
